import { Controller } from '@nestjs/common';

// 이 기능은 화면만 만든다.
// GET /loan-statements (listLoanStatements)는 다른 작업(TASK-107 등)에서 한 번만 만든다.
@Controller('api/v1')
export class FnSfr00907Controller {}

