import { useState } from 'react';
import { call, useData, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Badge, Num, DateText, Field, DateInput, Select, LookupSelect, RefName, ErrorText } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

const LOAN_TYPES: [string, string][] = [
  ['BORROWING', '차입'],
  ['LENDING', '대여'],
];

function loanTypeName(value: unknown): string {
  const found = LOAN_TYPES.find(([code]) => code === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr00907Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState<string>('');
  const [toDate, setToDate] = useState<string>('');
  const [loanType, setLoanType] = useState<string>('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState<number>(0);
  const [formError, setFormError] = useState<string>('');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | null>(async () => {
    if (!applied) {
      return null;
    }
    return call<Page>('GET', '/loan-statements', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page, role]);

  function search() {
    if (!fromDate || !toDate) {
      setFormError('조회 시작일과 종료일을 입력하세요.');
      return;
    }
    if (!loanType) {
      setFormError('차입/대여 구분을 선택하세요.');
      return;
    }
    if (fromDate > toDate) {
      setFormError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ fromDate, toDate, loanType, partnerId });
    notify('원장을 조회했습니다.');
  }

  function reset() {
    setFromDate('');
    setToDate('');
    setLoanType('');
    setPartnerId('');
    setFormError('');
    setApplied(null);
    setPage(0);
  }

  const items: Row[] = data ? data.items : [];
  const sum = (key: string) => items.reduce((acc, r) => acc + (Number(r[key]) || 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현재 쪽 합계</h2>
        <Tiles
          items={[
            ['발생금액', <Num value={sum('occurrenceAmount')} />],
            ['상환금액', <Num value={sum('repaymentAmount')} />],
            ['잔액', <Num value={sum('balanceAmount')} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>차입금·대여금 원장</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="차입/대여 구분" required>
            <Select value={loanType} onChange={setLoanType} options={LOAN_TYPES} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          rows={items}
          empty={loading ? '불러오는 중입니다.' : applied ? '조회된 원장이 없습니다.' : '조회 조건을 입력하고 조회하세요.'}
          onRowClick={(row) => setSelected(row)}
          columns={[
            { key: 'partnerId', label: '거래처', render: (r) => <RefName table="partner" role={role} value={r.partnerId} /> },
            { key: 'loanType', label: '차입/대여 구분', render: (r) => <>{loanTypeName(r.loanType)}</> },
            { key: 'occurrenceDate', label: '발생일자', render: (r) => <DateText value={r.occurrenceDate} /> },
            { key: 'occurrenceAmount', label: '발생금액', render: (r) => <Num value={r.occurrenceAmount} /> },
            { key: 'repaymentAmount', label: '상환금액', render: (r) => <Num value={r.repaymentAmount} /> },
            { key: 'balanceAmount', label: '잔액', render: (r) => <Num value={r.balanceAmount} /> },
            { key: 'isVoucherProcessed', label: '전표처리 여부', render: (r) => <Badge value={r.isVoucherProcessed ? '처리' : '미처리'} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {selected ? (
        <Drawer title="원장 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['차입금·대여금 명세 ID', String(selected.loanStatementId ?? '')],
              ['거래처', <RefName table="partner" role={role} value={selected.partnerId} />],
              ['차입/대여 구분', loanTypeName(selected.loanType)],
              ['발생일자', <DateText value={selected.occurrenceDate} />],
              ['발생금액', <Num value={selected.occurrenceAmount} />],
              ['상환금액', <Num value={selected.repaymentAmount} />],
              ['잔액', <Num value={selected.balanceAmount} />],
              ['전표처리 여부', <Badge value={selected.isVoucherProcessed ? '처리' : '미처리'} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
